#!/usr/bin/env node
/**
 * Renders the development report from finalize-change.js's result plus the agent's
 * dev-notes.json narrative. Status comes straight from the result JSON, never restated.
 *
 *   node scripts/render-dev-report.js --story JIRA-001
 *   node scripts/render-dev-report.js --all
 */
const fs = require('fs');
const path = require('path');
const {
  OUT_DIR, OUT_README,
  rel, readJsonIfPresent, listPlans, resolvePlan,
  resultPathFor, devNotesPathFor, devReportPathFor,
} = require('./lib/developer');

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i += 1) {
    const a = argv[i];
    if (a === '--story' || a === '-s') args.story = argv[++i];
    else if (a === '--all' || a === '-a') args.all = true;
    else if (a === '--help' || a === '-h') args.help = true;
  }
  return args;
}

function usage() {
  console.log('Render the development report.\n\n  node scripts/render-dev-report.js --story <ID>\n  node scripts/render-dev-report.js --all');
}

function statusFromResult(result) {
  if (!result) return null;
  if (!result.hasChanges) return 'Refused';
  return result.compiled ? 'Compiled' : 'Compile Failed';
}

function renderOne(plan) {
  if (plan.status !== 'Approved') {
    return { id: plan.id, skipped: true, reason: `plan Status is "${plan.status}", not "Approved" — nothing to implement yet.` };
  }
  const result = readJsonIfPresent(resultPathFor(plan.id));
  if (!result) return { id: plan.id, skipped: true, reason: `No ${rel(resultPathFor(plan.id))} — run finalize-change.js first.` };
  const notes = readJsonIfPresent(devNotesPathFor(plan.id));

  const status = statusFromResult(result);
  const lines = [];
  lines.push(`## ${plan.id} — ${plan.title}`, '');
  lines.push('| Field | Value |', '|---|---|');
  lines.push(`| **Status** | ${status} |`);
  lines.push(`| **Plan** | [${plan.id}](../02-story-analysis/${path.basename(plan.planFile)}) |`);
  if (result.diffFile) lines.push(`| **Diff** | [${result.diffFile}](../../../${result.diffFile}) |`);
  lines.push('');

  if (status === 'Refused') {
    lines.push('No changes were captured from the worktree — nothing was edited before ' +
      '`finalize-change.js` ran.', '');
    fs.mkdirSync(OUT_DIR, { recursive: true });
    fs.writeFileSync(devReportPathFor(plan.id), lines.join('\n'));
    return { id: plan.id, skipped: false, status };
  }

  if (notes) {
    lines.push('## Summary', '', notes.summary, '');
    lines.push('## Acceptance criteria addressed', '');
    for (const item of notes.acceptanceCriteriaAddressed || []) {
      lines.push(`- ${item.addressed ? '✅' : '❌'} **${item.criterion}** — ${item.howOrWhyNot}`);
    }
    lines.push('');
    if (notes.deviationsFromPlan && notes.deviationsFromPlan.length) {
      lines.push('## Deviations from the plan', '');
      for (const d of notes.deviationsFromPlan) lines.push(`- ${d}`);
      lines.push('');
    }
    if (notes.followUps && notes.followUps.length) {
      lines.push('## Follow-ups', '');
      for (const f of notes.followUps) lines.push(`- ${f}`);
      lines.push('');
    }
  } else {
    lines.push('_No developer narrative written yet (`.dev-notes.json` missing)._', '');
  }

  lines.push('## What changed', '');
  for (const f of result.changedFiles || []) lines.push(`- [${f}](../../../${f})`);
  lines.push('');

  lines.push('## Build output', '', '```', ...(result.steps || []).map((s) => `$ ${s.command} (exit ${s.exitCode})\n${s.output}`), '```', '');

  fs.mkdirSync(OUT_DIR, { recursive: true });
  fs.writeFileSync(devReportPathFor(plan.id), lines.join('\n'));
  return { id: plan.id, skipped: false, status };
}

const INDEX_MARKER = '<!-- AUTO-GENERATED TABLE — regenerated by 03_developer, do not hand-edit below this line -->';

function rewriteIndex() {
  if (!fs.existsSync(OUT_DIR)) return;
  const rows = fs.readdirSync(OUT_DIR)
    .filter((f) => /^dev_.+\.md$/i.test(f))
    .map((f) => {
      const text = fs.readFileSync(path.join(OUT_DIR, f), 'utf8');
      const id = f.replace(/^dev_/, '').replace(/\.md$/i, '');
      const title = (/^##\s+.+—\s*(.+)$/m.exec(text) || [])[1] || '(untitled)';
      const status = (/\|\s*\*\*Status\*\*\s*\|\s*([^|]+)\|/.exec(text) || [])[1] || 'unknown';
      return { id, title: title.trim(), status: status.trim() };
    })
    .sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }));

  const header = `# Step 03 — Development

Implemented changes for stories whose plan in [\`docs/agent_output/02-story-analysis/\`](../02-story-analysis/)
was marked \`Approved\`, written by \`03_developer\` and compiled inside a throwaway worktree —
never the real working tree.

`;
  const table = [INDEX_MARKER, ''];
  if (!rows.length) table.push('_No development reports yet._', '');
  else {
    table.push('| Story | Title | Status |', '|---|---|---|');
    for (const r of rows) table.push(`| ${r.id} | ${r.title} | ${r.status} |`);
    table.push('');
  }
  fs.writeFileSync(OUT_README, header + table.join('\n'));
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.help) return usage();

  let targets;
  if (args.all) {
    targets = listPlans().filter((p) => p.status === 'Approved');
    if (!targets.length) { console.log('No Approved plans found. Nothing to render.'); return; }
  } else {
    if (!args.story) throw new Error('Missing --story or --all.');
    targets = [resolvePlan(args.story)];
  }

  for (const plan of targets) {
    const result = renderOne(plan);
    if (result.skipped) console.log(`${result.id}: skipped — ${result.reason}`);
    else console.log(`${result.id}: ${result.status} -> ${rel(devReportPathFor(result.id))}`);
  }
  rewriteIndex();
}

try { main(); } catch (err) { console.error('Render failed:', err.message); process.exit(1); }
